class Solution {
  public String maskPII(String s) {
    if (s.indexOf('@') >= 0) {
      String t = s.toLowerCase();
      int at = t.indexOf('@');
      return t.charAt(0) + "*****" + t.substring(at - 1);
    }
    StringBuilder d = new StringBuilder();
    for (char c : s.toCharArray()) if (Character.isDigit(c)) d.append(c);
    int n = d.length();
    String local = "***-***-" + d.substring(n - 4);
    if (n == 10) return local;
    return "+" + "*".repeat(n - 10) + "-" + local;
  }
}
